(()=>{const essay=window.ESSAY_MEMORY_LESSONS["opinion:13"];if(!essay)throw Error('Missing exact source for opinion:13');essay.learningSentences=[{"paragraph":0,"index":0,"role":"Background（背景）","english":"In most areas of life, meaningful success does not happen by accident.","chinese":"在生活的大多數範疇中，有意義的成功並不是偶然發生的。","words":[["In",0,0.08],["most",0.08,0.2],["areas",0.2,0.56],["of",0.56,0.84],["life",0.84,1.18],["meaningful",1.5,1.86],["success",1.86,2.4],["does",2.4,2.82],["not",2.82,3.02],["happen",3.02,3.4],["by",3.4,3.6],["accident",3.6,4.02]],"start":0,"end":4.7219999999999995,"sourceIndices":[0]},{"paragraph":0,"index":1,"role":"Transition（轉折）","english":"Many people therefore believe that ambition is indispensable to achievement.","chinese":"因此，許多人相信，抱負對成就而言是不可或缺的。","words":[["Many",4.802,5.002],["people",5.002,5.402],["therefore",5.642,5.882],["believe",5.882,6.322],["that",6.322,6.702],["ambition",6.702,7.002],["is",7.002,7.702],["indispensable",7.702,8.162],["to",8.162,8.702],["achievement",8.702,9.022]],"start":4.6419999999999995,"end":9.844,"sourceIndices":[1]},{"paragraph":0,"index":2,"role":"Stance（立場）","english":"I completely agree, because ambition gives people both the endurance to continue through difficulty and the drive to improve until opportunities become tangible results.","chinese":"我完全同意，因為抱負既給予人們在困難中堅持下去的耐力，也給予人們不斷進步的動力，直到機會轉化為具體成果。","words":[["I",9.924,10.024],["completely",10.024,10.244],["agree",10.244,10.884],["because",11.484,11.744],["ambition",11.744,11.984],["gives",11.984,12.544],["people",12.544,12.944],["both",12.944,13.284],["the",13.284,13.504],["endurance",13.504,13.884],["to",13.884,14.244],["continue",14.244,14.664],["through",14.664,15.004],["difficulty",15.004,15.424],["and",15.934,16.324],["the",16.324,16.444],["drive",16.444,16.644],["to",16.644,16.944],["improve",16.944,17.384],["until",17.384,17.984],["opportunities",17.984,18.524],["become",18.524,19.124],["tangible",19.124,19.624],["results",19.624,20.204]],"start":9.764,"end":21.231,"sourceIndices":[2,3]},{"paragraph":1,"index":0,"role":"Topic Sentence（主題句）","english":"The first reason ambition is essential is that it sustains effort over long periods of time.","chinese":"抱負之所以重要，第一個原因是它能讓人長時間維持努力。","words":[["The",21.311,21.391],["first",21.391,21.631],["reason",21.631,22.011],["ambition",22.011,22.351],["is",22.351,22.931],["essential",22.931,23.251],["is",23.251,24.131],["that",24.131,24.311],["it",24.311,24.411],["sustains",24.411,24.931],["effort",24.931,25.271],["over",25.271,25.691],["long",25.691,25.951],["periods",25.951,26.471],["of",26.471,26.671],["time",26.671,26.951]],"start":21.151,"end":27.547,"sourceIndices":[4]},{"paragraph":1,"index":1,"role":"Elaboration（闡述）","english":"Real success normally demands discipline, and ambitious people are far more willing to tolerate inconvenience in order to reach a goal.","chinese":"真正的成功通常需要紀律，而有抱負的人為了達成目標，往往更願意忍受種種不便。","words":[["Real",27.627,27.847],["success",27.847,28.207],["normally",28.207,28.867],["demands",28.867,29.427],["discipline",29.427,29.907],["and",30.747,30.767],["ambitious",30.767,31.167],["people",31.167,31.667],["are",31.667,31.927],["far",31.927,32.167],["more",32.167,32.447],["willing",32.447,32.767],["to",32.767,33.067],["tolerate",33.067,33.487],["inconvenience",33.487,34.027],["in",34.027,35.007],["order",35.007,35.167],["to",35.167,35.427],["reach",35.427,35.607],["a",35.607,35.767],["goal",35.767,35.927]],"start":27.467,"end":36.531,"sourceIndices":[5]},{"paragraph":1,"index":2,"role":"Example（例子）","english":"A student aiming for a highly competitive scholarship, for example, may spend evenings revising, reduce social activities and practise under constant pressure for months.","chinese":"例如，一名以競爭激烈的獎學金為目標的學生，可能會在晚上持續溫習、減少社交活動，並在持續壓力下練習數月。","words":[["A",36.611,36.671],["student",36.671,36.971],["aiming",36.971,37.311],["for",37.311,37.691],["a",37.691,37.811],["highly",37.811,38.091],["competitive",38.091,38.671],["scholarship",38.671,39.351],["for",39.671,39.751],["example",39.751,40.071],["may",40.811,40.871],["spend",40.871,41.151],["evenings",41.151,41.491],["revising",41.491,42.391],["reduce",42.931,43.131],["social",43.131,43.731],["activities",43.731,44.071],["and",44.071,44.591],["practise",44.591,44.851],["under",44.851,45.351],["constant",45.351,45.651],["pressure",45.651,46.091],["for",46.091,46.531],["months",46.531,46.711]],"start":36.451,"end":47.434000000000005,"sourceIndices":[6]},{"paragraph":1,"index":3,"role":"Conclusion / Elaboration（結論／闡述）","english":"Just as importantly, ambition helps people recover from setbacks instead of abandoning their plans at the first disappointment.","chinese":"同樣重要的是，抱負能幫助人們在遭遇挫折後重新站起來，而不是在第一次失望時就放棄原本的計劃。","words":[["Just",47.514,47.774],["as",47.774,47.974],["importantly",47.974,48.454],["ambition",49.194,49.374],["helps",49.374,49.794],["people",49.794,50.154],["recover",50.154,50.434],["from",50.434,50.914],["setbacks",50.914,51.174],["instead",51.174,52.094],["of",52.094,52.334],["abandoning",52.334,52.674],["their",52.674,52.994],["plans",52.994,53.354],["at",53.354,53.774],["the",53.774,53.874],["first",53.874,54.114],["disappointment",54.114,54.714]],"start":47.354000000000006,"end":55.5,"sourceIndices":[7]},{"paragraph":1,"index":4,"role":"Example（例子）","english":"When such a student performs badly in an early mock exam, ambition encourages them to analyse weaknesses and try again rather than conclude that success is impossible.","chinese":"當這樣的學生在早期模擬考中表現欠佳時，抱負會促使他們分析自己的弱點，並再次嘗試，而不是直接認定成功是不可能的。","words":[["When",55.58,55.7],["such",55.7,55.9],["a",55.9,56.08],["student",56.08,56.38],["performs",56.38,56.66],["badly",56.66,57.24],["in",57.24,57.64],["an",57.64,57.72],["early",57.72,58.02],["mock",58.02,58.22],["exam",58.22,58.68],["ambition",59.66,59.72],["encourages",59.72,60.28],["them",60.28,60.66],["to",60.66,60.86],["analyse",60.86,61.18],["weaknesses",61.18,61.66],["and",62.2,62.54],["try",62.54,62.74],["again",62.74,63.14],["rather",63.14,63.64],["than",63.64,63.94],["conclude",63.94,64.28],["that",64.28,64.62],["success",64.62,64.94],["is",64.94,65.4],["impossible",65.4,65.76]],"start":55.42,"end":66.659,"sourceIndices":[8]},{"paragraph":1,"index":5,"role":"Conclusion（結論）","english":"Because achievement usually comes after sacrifice and failure, this kind of persistence is not optional; it is fundamental.","chinese":"因為成就通常是在犧牲與失敗之後才出現，這種堅持是根本條件，絕不可缺少。","words":[["Because",66.739,66.939],["achievement",66.939,67.359],["usually",67.359,67.899],["comes",67.899,68.399],["after",68.399,68.739],["sacrifice",68.739,69.339],["and",69.339,69.679],["failure",69.679,69.999],["this",70.579,70.739],["kind",70.739,70.959],["of",70.959,71.079],["persistence",71.079,71.359],["is",71.359,71.899],["not",71.899,72.139],["optional",72.139,72.619],["it",73.279,73.359],["is",73.359,73.459],["fundamental",73.459,73.739]],"start":66.57900000000001,"end":74.931,"sourceIndices":[9]},{"paragraph":2,"index":0,"role":"Topic Sentence（主題句）","english":"Ambition is equally important because it pushes people beyond mere competence.","chinese":"抱負同樣重要，因為它能推動人們超越僅僅「勝任」的層次。","words":[["Ambition",75.011,75.491],["is",75.491,75.811],["equally",75.811,76.151],["important",76.151,76.731],["because",76.731,77.471],["it",77.471,77.651],["pushes",77.651,77.851],["people",77.851,78.331],["beyond",78.331,78.751],["mere",78.751,78.951],["competence",78.951,79.351]],"start":74.851,"end":80.224,"sourceIndices":[10]},{"paragraph":2,"index":1,"role":"Elaboration（闡述）","english":"Those who genuinely want to succeed do not simply repeat familiar routines; they actively seek better methods, higher standards and more demanding responsibilities.","chinese":"真正想成功的人不會只是重複熟悉的做法；他們會主動尋求更好的方法、更高的標準，以及更具挑戰性的責任。","words":[["Those",80.304,80.504],["who",80.504,80.744],["genuinely",80.744,81.084],["want",81.084,81.504],["to",81.504,81.624],["succeed",81.624,81.964],["do",81.964,82.304],["not",82.304,82.484],["simply",82.484,82.864],["repeat",82.864,83.264],["familiar",83.264,83.684],["routines",83.684,84.144],["they",85.104,85.184],["actively",85.184,85.604],["seek",85.604,85.984],["better",85.984,86.304],["methods",86.304,86.784],["higher",87.144,87.464],["standards",87.464,87.924],["and",87.924,88.604],["more",88.604,88.784],["demanding",88.784,89.084],["responsibilities",89.084,89.844]],"start":80.144,"end":90.807,"sourceIndices":[11]},{"paragraph":2,"index":2,"role":"Example（例子）","english":"An ambitious employee, for instance, is more likely to learn new software, request feedback and strengthen communication skills in order to prepare for promotion.","chinese":"例如，一位有抱負的員工更有可能主動學習新軟件、要求回饋，並加強溝通能力，為晉升作準備。","words":[["An",90.887,90.987],["ambitious",90.987,91.307],["employee",91.307,91.847],["for",92.187,92.287],["instance",92.287,92.507],["is",93.187,93.327],["more",93.327,93.487],["likely",93.487,93.827],["to",93.827,94.107],["learn",94.107,94.327],["new",94.327,94.567],["software",94.567,95.047],["request",95.687,95.987],["feedback",95.987,96.427],["and",96.427,96.987],["strengthen",96.987,97.307],["communication",97.307,97.767],["skills",97.767,98.487],["in",98.487,99.167],["order",99.167,99.367],["to",99.367,99.587],["prepare",99.587,99.807],["for",99.807,100.107],["promotion",100.107,100.387]],"start":90.727,"end":101.263,"sourceIndices":[12]},{"paragraph":2,"index":3,"role":"Elaboration（闡述）","english":"Ambition also makes people alert to opportunities that less driven individuals often ignore.","chinese":"抱負也會讓人更敏銳地留意那些較缺乏動力的人往往忽略的機會。","words":[["Ambition",101.343,101.803],["also",101.803,102.223],["makes",102.223,102.643],["people",102.643,102.943],["alert",102.943,103.363],["to",103.363,103.583],["opportunities",103.583,104.183],["that",104.183,104.903],["less",104.903,105.203],["driven",105.203,105.523],["individuals",105.523,106.283],["often",106.283,106.563],["ignore",106.563,107.063]],"start":101.183,"end":107.729,"sourceIndices":[13]},{"paragraph":2,"index":4,"role":"Example（例子）","english":"The same worker may volunteer for a difficult project or propose an innovative idea to senior managers, thereby gaining both experience and visibility.","chinese":"同一位員工可能會主動請纓參與艱難的項目，或向高層管理人員提出創新構想，從而同時獲得經驗與曝光機會。","words":[["The",107.809,107.869],["same",107.869,108.089],["worker",108.089,108.389],["may",108.389,108.889],["volunteer",108.889,109.409],["for",109.409,109.809],["a",109.809,109.909],["difficult",109.909,110.129],["project",110.129,110.729],["or",110.729,111.409],["propose",111.409,111.869],["an",111.869,112.069],["innovative",112.069,112.369],["idea",112.369,112.869],["to",112.869,113.189],["senior",113.189,113.389],["managers",113.389,113.949],["thereby",114.549,114.929],["gaining",114.929,115.469],["both",115.469,115.769],["experience",115.769,116.269],["and",116.269,116.989],["visibility",116.989,117.349]],"start":107.649,"end":118.205,"sourceIndices":[14]},{"paragraph":2,"index":5,"role":"Conclusion（結論）","english":"As a result, ambition does not just improve a person’s ability; it places that ability in situations where it can be recognised and rewarded.","chinese":"因此，抱負不僅能提升一個人的能力，還能把這種能力放進能夠被看見和獲得回報的情境之中。","words":[["As",118.285,118.405],["a",118.405,118.505],["result",118.505,118.845],["ambition",119.165,119.585],["does",119.585,119.925],["not",119.925,120.145],["just",120.145,120.425],["improve",120.425,120.805],["a",120.805,121.005],["person’s",121.005,121.325],["ability",121.325,121.805],["it",122.525,122.625],["places",122.625,122.865],["that",122.865,123.305],["ability",123.305,123.625],["in",123.625,123.985],["situations",123.985,124.325],["where",124.325,125.365],["it",125.365,125.465],["can",125.465,125.565],["be",125.565,125.665],["recognised",125.665,125.985],["and",125.985,126.785],["rewarded",126.785,127.105]],"start":118.125,"end":128.16299999999998,"sourceIndices":[15]},{"paragraph":3,"index":0,"role":"Reiterating Stance（重申立場）","english":"In conclusion, I completely agree that ambition is essential for success.","chinese":"總而言之，我完全同意抱負對成功而言是不可或缺的。","words":[["In",128.243,128.343],["conclusion",128.343,128.703],["I",129.463,129.563],["completely",129.563,129.803],["agree",129.803,130.423],["that",130.423,130.663],["ambition",130.663,130.863],["is",130.863,131.343],["essential",131.343,131.583],["for",131.583,132.003],["success",132.003,132.323]],"start":128.083,"end":133.093,"sourceIndices":[16]},{"paragraph":3,"index":1,"role":"Reiterating Arguments（重申論點）","english":"It enables people to endure sacrifice, recover from failure, pursue improvement and seize opportunities, and these are precisely the conditions in which meaningful achievement becomes possible.","chinese":"它使人能夠承受犧牲、從失敗中恢復、追求進步並把握機會，而這些正是有意義的成就得以實現的條件。","words":[["It",133.173,133.293],["enables",133.293,133.533],["people",133.533,134.013],["to",134.013,134.333],["endure",134.333,134.633],["sacrifice",134.633,135.253],["recover",135.953,136.213],["from",136.213,136.613],["failure",136.613,136.893],["pursue",137.493,137.793],["improvement",137.793,138.373],["and",138.373,138.713],["seize",138.713,138.953],["opportunities",138.953,139.393],["and",140.333,140.433],["these",140.433,140.633],["are",140.633,140.873],["precisely",140.873,141.293],["the",141.293,141.653],["conditions",141.653,141.993],["in",141.993,142.513],["which",142.513,142.673],["meaningful",142.673,143.013],["achievement",143.013,143.753],["becomes",143.753,144.333],["possible",144.333,144.693]],"start":133.013,"end":145.09300000000002,"sourceIndices":[17]}];essay.meta={"topic":"抱負、持續努力與把握機會","summary":"作者完全同意抱負對成功重要：它幫助人長期投入、受挫後再試，也促進技能改進、主動承擔，使能力有機會被看見與回報。"};essay.support={"sentences":[{"simple":"In most parts of life, real success does not just happen by chance.","synonyms":[{"original":"most areas of life","simple":"most parts of life","meaning":"生活大部分範疇"},{"original":"meaningful success","simple":"real success","meaning":"有意義的成功"},{"original":"does not happen by accident","simple":"does not just happen by chance","meaning":"並非偶然發生"}],"chunks":["In most areas of life,","meaningful success does not happen by accident."],"simpleChunks":["In most parts of life,","real success does not just happen by chance."]},{"simple":"So many people think wanting very much to succeed is needed to achieve things.","synonyms":[{"original":"therefore","simple":"So","meaning":"因此"},{"original":"ambition","simple":"wanting very much to succeed","meaning":"抱負"},{"original":"indispensable to achievement","simple":"needed to achieve things","meaning":"對成就不可缺少"}],"chunks":["Many people therefore believe","that ambition is indispensable to achievement."],"simpleChunks":["So many people think","wanting very much to succeed is needed to achieve things."]},{"simple":"I fully agree because wanting very much to succeed helps people keep going when things are hard and makes them work to improve until chances become real results.","synonyms":[{"original":"completely agree","simple":"fully agree","meaning":"完全同意"},{"original":"ambition","simple":"wanting very much to succeed","meaning":"抱負"},{"original":"endurance to continue through difficulty","simple":"keep going when things are hard","meaning":"克服困難的耐力"},{"original":"drive to improve","simple":"work to improve","meaning":"求進步的動力"},{"original":"opportunities become tangible results","simple":"chances become real results","meaning":"機會變成具體成果"}],"chunks":["I completely agree,","because ambition gives people both the endurance to continue through difficulty","and the drive to improve until opportunities become tangible results."],"simpleChunks":["I fully agree","because wanting very much to succeed helps people keep going when things are hard","and makes them work to improve until chances become real results."]},{"simple":"First, wanting very much to succeed matters because it helps people keep working for a long time.","synonyms":[{"original":"The first reason","simple":"First","meaning":"第一個原因"},{"original":"ambition","simple":"wanting very much to succeed","meaning":"抱負"},{"original":"essential","simple":"matters","meaning":"重要"},{"original":"sustains effort over long periods of time","simple":"helps people keep working for a long time","meaning":"維持長時間努力"}],"chunks":["The first reason ambition is essential","is that it sustains effort over long periods of time."],"simpleChunks":["First, wanting very much to succeed matters","because it helps people keep working for a long time."]},{"simple":"Real success usually needs self-control, and people who really want to succeed are much more willing to put up with difficulties to reach a goal.","synonyms":[{"original":"normally demands discipline","simple":"usually needs self-control","meaning":"通常需要紀律"},{"original":"ambitious people","simple":"people who really want to succeed","meaning":"有抱負的人"},{"original":"far more willing","simple":"much more willing","meaning":"更願意"},{"original":"tolerate inconvenience","simple":"put up with difficulties","meaning":"忍受不便"}],"chunks":["Real success normally demands discipline,","and ambitious people are far more willing to tolerate inconvenience","in order to reach a goal."],"simpleChunks":["Real success usually needs self-control,","and people who really want to succeed are much more willing","to put up with difficulties to reach a goal."]},{"simple":"For example, a student who wants a hard-to-win scholarship may study in the evenings, spend less time with friends and practise for months even under pressure.","synonyms":[{"original":"highly competitive scholarship","simple":"hard-to-win scholarship","meaning":"競爭激烈的獎學金"},{"original":"spend evenings revising","simple":"study in the evenings","meaning":"晚上溫習"},{"original":"reduce social activities","simple":"spend less time with friends","meaning":"減少社交活動"},{"original":"constant pressure","simple":"pressure","meaning":"持續壓力"}],"chunks":["A student aiming for a highly competitive scholarship, for example,","may spend evenings revising, reduce social activities","and practise under constant pressure for months."],"simpleChunks":["For example, a student who wants a hard-to-win scholarship","may study in the evenings, spend less time with friends","and practise for months even under pressure."]},{"simple":"Also, wanting very much to succeed helps people try again after problems instead of giving up after the first disappointment.","synonyms":[{"original":"Just as importantly","simple":"Also","meaning":"同樣重要"},{"original":"ambition","simple":"wanting very much to succeed","meaning":"抱負"},{"original":"recover from setbacks","simple":"try again after problems","meaning":"從挫折中恢復"},{"original":"abandoning their plans","simple":"giving up","meaning":"放棄計劃"}],"chunks":["Just as importantly, ambition helps people recover from setbacks","instead of abandoning their plans at the first disappointment."],"simpleChunks":["Also, wanting very much to succeed helps people try again after problems","instead of giving up after the first disappointment."]},{"simple":"When that student does badly in an early practice exam, their goal can make them look at what went wrong and try again rather than decide success is impossible.","synonyms":[{"original":"performs badly","simple":"does badly","meaning":"表現欠佳"},{"original":"mock exam","simple":"practice exam","meaning":"模擬考"},{"original":"analyse weaknesses","simple":"look at what went wrong","meaning":"分析弱點"},{"original":"conclude","simple":"decide","meaning":"下結論"}],"chunks":["When such a student performs badly in an early mock exam,","ambition encourages them to analyse weaknesses and try again","rather than conclude that success is impossible."],"simpleChunks":["When that student does badly in an early practice exam,","their goal can make them look at what went wrong and try again","rather than decide success is impossible."]},{"simple":"Because success often comes after giving up time and facing failure, this kind of continuing effort is necessary.","synonyms":[{"original":"achievement","simple":"success","meaning":"成就"},{"original":"sacrifice","simple":"giving up time","meaning":"犧牲"},{"original":"persistence","simple":"continuing effort","meaning":"堅持"},{"original":"not optional; it is fundamental","simple":"necessary","meaning":"不可缺少"}],"chunks":["Because achievement usually comes after sacrifice and failure,","this kind of persistence is not optional; it is fundamental."],"simpleChunks":["Because success often comes after giving up time and facing failure,","this kind of continuing effort is necessary."]},{"simple":"Wanting very much to succeed matters just as much because it pushes people to do more than just do their job well enough.","synonyms":[{"original":"Ambition","simple":"Wanting very much to succeed","meaning":"抱負"},{"original":"equally important","simple":"matters just as much","meaning":"同樣重要"},{"original":"beyond mere competence","simple":"do more than just do their job well enough","meaning":"超越僅僅勝任"}],"chunks":["Ambition is equally important","because it pushes people beyond mere competence."],"simpleChunks":["Wanting very much to succeed matters just as much","because it pushes people to do more than just do their job well enough."]},{"simple":"People who truly want to succeed do not just repeat what they know; they look for better ways, higher goals and harder jobs.","synonyms":[{"original":"genuinely","simple":"truly","meaning":"真正"},{"original":"familiar routines","simple":"what they know","meaning":"熟悉的做法"},{"original":"actively seek better methods","simple":"look for better ways","meaning":"主動尋求更好方法"},{"original":"more demanding responsibilities","simple":"harder jobs","meaning":"更具挑戰的責任"}],"chunks":["Those who genuinely want to succeed do not simply repeat familiar routines;","they actively seek better methods, higher standards","and more demanding responsibilities."],"simpleChunks":["People who truly want to succeed do not just repeat what they know;","they look for better ways, higher goals and harder jobs."]},{"simple":"For example, a worker who really wants to succeed is more likely to learn new computer programs, ask for advice and improve how they speak to others so they can get ready to move up at work.","synonyms":[{"original":"ambitious employee","simple":"worker who really wants to succeed","meaning":"有抱負的員工"},{"original":"new software","simple":"new computer programs","meaning":"新軟件"},{"original":"request feedback","simple":"ask for advice","meaning":"要求回饋"},{"original":"strengthen communication skills","simple":"improve how they speak to others","meaning":"加強溝通能力"},{"original":"prepare for promotion","simple":"get ready to move up at work","meaning":"為晉升作準備"}],"chunks":["An ambitious employee, for instance, is more likely to learn new software,","request feedback and strengthen communication skills","in order to prepare for promotion."],"simpleChunks":["For example, a worker who really wants to succeed is more likely to learn new computer programs,","ask for advice and improve how they speak to others","so they can get ready to move up at work."]},{"simple":"Wanting very much to succeed also helps people notice chances that people who do not want to succeed as strongly often miss.","synonyms":[{"original":"Ambition","simple":"Wanting very much to succeed","meaning":"抱負"},{"original":"alert to opportunities","simple":"notice chances","meaning":"留意機會"},{"original":"less driven individuals","simple":"people who do not want to succeed as strongly","meaning":"較缺乏動力的人"},{"original":"ignore","simple":"miss","meaning":"忽略"}],"chunks":["Ambition also makes people alert to opportunities","that less driven individuals often ignore."],"simpleChunks":["Wanting very much to succeed also helps people notice chances","that people who do not want to succeed as strongly often miss."]},{"simple":"The same worker may offer to do a hard project or suggest a new idea to senior managers, and so gain both experience and attention.","synonyms":[{"original":"volunteer for a difficult project","simple":"offer to do a hard project","meaning":"主動請纓艱難項目"},{"original":"propose an innovative idea","simple":"suggest a new idea","meaning":"提出創新構想"},{"original":"thereby gaining","simple":"and so gain","meaning":"從而得到"},{"original":"visibility","simple":"attention","meaning":"曝光機會"}],"chunks":["The same worker may volunteer for a difficult project","or propose an innovative idea to senior managers,","thereby gaining both experience and visibility."],"simpleChunks":["The same worker may offer to do a hard project","or suggest a new idea to senior managers,","and so gain both experience and attention."]},{"simple":"As a result, wanting very much to succeed not only improves a person’s skills but also lets other people see and value those skills.","synonyms":[{"original":"Ambition","simple":"wanting very much to succeed","meaning":"抱負"},{"original":"ability","simple":"skills","meaning":"能力"},{"original":"recognised and rewarded","simple":"see and value","meaning":"被看見並獲得回報"}],"chunks":["As a result, ambition does not just improve a person’s ability;","it places that ability in situations","where it can be recognised and rewarded."],"simpleChunks":["As a result, wanting very much to succeed not only improves a person’s skills","but also lets other people see and value those skills."]},{"simple":"In short, I fully agree that wanting very much to succeed is needed for success.","synonyms":[{"original":"In conclusion","simple":"In short","meaning":"總而言之"},{"original":"completely agree","simple":"fully agree","meaning":"完全同意"},{"original":"ambition","simple":"wanting very much to succeed","meaning":"抱負"},{"original":"essential","simple":"needed","meaning":"不可缺少"}],"chunks":["In conclusion, I completely agree","that ambition is essential for success."],"simpleChunks":["In short, I fully agree","that wanting very much to succeed is needed for success."]},{"simple":"It helps people give up things they enjoy, try again after failure, get better and take chances, and these are exactly the things that make real success possible.","synonyms":[{"original":"enables","simple":"helps","meaning":"使人能夠"},{"original":"endure sacrifice","simple":"give up things they enjoy","meaning":"承受犧牲"},{"original":"recover from failure","simple":"try again after failure","meaning":"從失敗中恢復"},{"original":"pursue improvement","simple":"get better","meaning":"追求進步"},{"original":"seize opportunities","simple":"take chances","meaning":"把握機會"},{"original":"meaningful achievement","simple":"real success","meaning":"有意義的成就"}],"chunks":["It enables people to endure sacrifice, recover from failure,","pursue improvement and seize opportunities,","and these are precisely the conditions","in which meaningful achievement becomes possible."],"simpleChunks":["It helps people give up things they enjoy, try again after failure,","get better and take chances,","and these are exactly the things that make real success possible."]}],"intro":[{"type":"quiz","prompt":"作者如何判斷抱負對有意義的成功是否重要？","options":["完全同意它重要：抱負支持人在困難中堅持，亦推動人改進和把握機會","完全反對：成功只由偶然機會決定，努力沒有作用","只同意抱負有助練習，但認為它會阻礙人看見機會","沒有表態：文章只描述幾份工作的名稱"],"correct":0,"why":"引言與結論都說 completely agree；兩段分別分析堅持與超越「僅僅勝任」。"},{"type":"multi","prompt":"選出正文的兩條不同論證線","detail":"選兩項，再按「確認」。","options":["抱負令人願意長期付出，受挫後分析弱點並再次嘗試","抱負推動人學新方法、提升能力，並主動把握可被看見的機會","抱負保證人在第一次嘗試時絕不失敗","抱負只等於職位名稱，與日常行動無關"],"correct":[0,1],"why":"第一主體段談獎學金準備和模擬考失利；第二主體段談員工學技能、主動承擔並獲得曝光。"}],"route":[{"type":"sequence","prompt":"先排好全文四段","detail":"依照原文的推進次序，逐一點選下一步。","items":[{"title":"引言 · 立場與兩項作用","body":"完全同意抱負重要，因它給人堅持的耐力和改進的動力。"},{"title":"主體段一 · 長期堅持","body":"獎學金申請者為目標持續練習，模擬考失利後分析弱點再試。"},{"title":"主體段二 · 改進與機會","body":"員工學技能、要求回饋，並主動接難項目，使能力能被看見。"},{"title":"結論 · 成果形成條件","body":"重申完全同意，歸納付出、從失敗恢復、改進和把握機會。"}],"why":"持續投入與受挫再試 → 主動改進與抓住機會 → 有意義的成果才可能出現。"}],"evidence":[{"type":"quiz","prompt":"為甚麼第一主體段說抱負能維持長時間的努力？","options":["有強烈目標的人較願意承受不便，持續做達成目標所需的事","抱負令任何目標立即完成，毋須紀律","有抱負者一定不用犧牲社交或休息時間","文章認為長期練習與有意義的成功完全無關"],"correct":0,"why":"原文說 Real success normally demands discipline，並指出 ambitious people 更願意 tolerate inconvenience。"},{"type":"quiz","prompt":"獎學金學生的例子具體列出哪些付出？","options":["晚上溫習、減少社交、在壓力下練習數月","只在頒獎前一天看一眼申請表","依靠他人替自己參加所有練習","完全放棄獎學金目標以避免任何不便"],"correct":0,"why":"例子同時列時間、社交和長期壓力的代價，使「紀律」可見。"},{"type":"quiz","prompt":"學生早期模擬考表現欠佳時，抱負促使甚麼反應？","options":["分析弱點並再試，而非立即認定自己不可能成功","因一次失利便停止所有準備","只重複同一錯誤，不檢視弱點","保證下一次考試必然取得第一名"],"correct":0,"why":"原文的 analyse weaknesses and try again 與 conclude that success is impossible 形成對照。"},{"type":"quiz","prompt":"「超越僅僅勝任」在員工例子中是甚麼行動？","options":["學新軟件、要求回饋、改善溝通，為晉升作準備","只重複自己已熟悉的做法，不聽意見","每天更換職位名稱，但不學任何新技能","把改善溝通視為與職場發展完全無關"],"correct":0,"why":"第二主體段由 better methods 等一般原則，轉到員工的三項具體改進。"},{"type":"quiz","prompt":"為甚麼光有更好的能力，仍不等於能力會被認可？","options":["人還要主動接項目或提出構想，讓能力出現在可被看見的場合","能力一提高，所有主管便必然即時知道","員工越少參與工作，能力就越容易獲得認可","文章認為曝光機會會自動降低一切技能"],"correct":0,"why":"結尾的 not just improve...; it places that ability in situations where... 把能力培養與可見性分開。"},{"type":"quiz","prompt":"結論列出的四項作用如何對應正文？","options":["承受犧牲與從失敗恢復對應第一段；追求改進與把握機會對應第二段","四項都只指公司薪金，與學生或員工行動無關","四項都在要求人停止練習和拒絕新項目","結論首次提出完全陌生的第四個主題"],"correct":0,"why":"最後一句依序回收 endure sacrifice、recover from failure、pursue improvement、seize opportunities。"}],"logic":[{"type":"sequence","prompt":"第一主體段：抱負如何支持長期堅持？","detail":"依照原文的推進次序，逐一點選下一步。","items":[{"title":"首項理由","body":"抱負使人長時間維持努力。"},{"title":"必需代價","body":"成功需要紀律；有目標者較願意承受不便。"},{"title":"學生例子","body":"為競爭激烈的獎學金，學生晚上溫習、減少社交，練習數月。"},{"title":"受挫情況","body":"學生在早期模擬考中表現欠佳。"},{"title":"下一步","body":"分析弱點、再次嘗試，不因一次失望便放棄。"},{"title":"段落結論","body":"成果常在犧牲與失敗後出現，因此堅持不可缺。"}],"why":"抱負 → 願意長期付出 → 失敗後仍分析再試 → 堅持成為成果的必要條件。"},{"type":"sequence","prompt":"第二主體段：抱負如何把能力變成成果？","detail":"依照原文的推進次序，逐一點選下一步。","items":[{"title":"新理由","body":"抱負推人超越僅僅勝任的水平。"},{"title":"改進行動","body":"主動尋找更好方法、更高標準和更難責任。"},{"title":"員工例子","body":"學新軟件、要求回饋、改善溝通，準備晉升。"},{"title":"機會意識","body":"留意較少動力者容易忽略的機會。"},{"title":"主動參與","body":"請纓難項目或向管理層提出新意見。"},{"title":"雙重結果","body":"能力提高，也進入能被看見與獲得回報的場合。"}],"why":"不滿足於現狀 → 提升技能 → 看見並主動接住機會 → 能力獲認可。"}],"structures":[{"id":"model-essay-13-ielts-opinion-frame-01","frame":"In [討論範圍], [有價值的成果] does not happen by accident","meaning":"先劃定討論範圍，再指出成果不是偶然出現，為後文解釋條件作開場。","usage":"開頭要避免把成就當成運氣，準備分析其形成條件時。","source":{"paragraph":1,"sentence":1},"parts":[{"text":"In ","kind":"link","label":"設定討論範圍"},{"text":"most areas of life","kind":"slot","label":"討論範圍"},{"text":", ","kind":"link","label":"接核心觀察"},{"text":"meaningful success","kind":"slot","label":"有價值的成果"},{"text":" does not happen by accident.","kind":"link","label":"否定偶然性"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In most workplaces, useful skills do not develop by accident.","Many parents therefore believe that daily reading helps children build confidence.","Learning to play an instrument normally demands practice, and serious pupils are more willing to give up free evenings in order to improve.","In conclusion, I completely agree that patient practice is essential for learning a language."],"correct":0,"explanations":["In... 指定討論範圍，do not...by accident 否定偶然性，為後文原因鋪路。","這句是依前文轉述他人看法，沒有解釋成果本身的形成。","這句說明目標需要甚麼品質，以及人為何願意付出代價。","這句是結論中的立場重申，未列出四個形成成果的條件。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-02","frame":"Many people therefore believe that [由前述觀察引出的看法]","meaning":"therefore 表示他人的看法接續前一句的觀察；believe that 仍標示這是被轉述的主張。","usage":"提出一項普遍情況後，要交代由此產生的常見看法時。","source":{"paragraph":1,"sentence":2},"parts":[{"text":"Many people therefore believe that ","kind":"link","label":"由背景轉述常見看法"},{"text":"ambition is indispensable to achievement.","kind":"slot","label":"由前述觀察引出的看法"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Many parents therefore believe that daily reading helps children build confidence.","In most workplaces, useful skills do not develop by accident.","The first reason patient teaching matters is that it keeps children practising over many months.","Curiosity is equally important because it pushes students beyond memorising answers."],"correct":0,"explanations":["therefore 把前一句的觀察接到一些人提出的看法。","這句只設定範圍並否定偶然形成，沒有列舉行動或提出政策。","這句點明第一個主體段的核心原因，沒有並列兩項作用。","這句由先前的堅持轉向能力提升，沒有重述第一段的失敗例子。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-03","frame":"I completely agree, because [特質] gives people both [持續能力] and [改進動力] until [機會變成成果]","meaning":"先亮出完全同意，再列同一特質提供的兩種作用，並把它們連到可見成果。","usage":"引言要以「能堅持」與「會改進」兩條正文主線預告理由時。","source":{"paragraph":1,"sentence":3},"parts":[{"text":"I completely agree, because ","kind":"link","label":"表明立場並引出理由"},{"text":"ambition","kind":"slot","label":"特質"},{"text":" gives people both ","kind":"link","label":"並列兩項作用"},{"text":"the endurance to continue through difficulty","kind":"slot","label":"持續能力"},{"text":" and ","kind":"link","label":"接第二項作用"},{"text":"the drive to improve","kind":"slot","label":"改進動力"},{"text":" until ","kind":"link","label":"指出達成結果的進程"},{"text":"opportunities become tangible results.","kind":"slot","label":"機會變成成果"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["I completely agree, because regular practice gives learners both stronger memory and the confidence to speak until new words become useful in conversation.","Many parents therefore believe that daily reading helps children build confidence.","Learning to play an instrument normally demands practice, and serious pupils are more willing to give up free evenings in order to improve.","Because learning a language involves mistakes and repeated practice, continuing after a weak test result is necessary; it is part of progress."],"correct":0,"explanations":["because 指出同意的理由，both...and 並列兩種助力，until 指向成果。","這句是依前文轉述他人看法，沒有解釋成果本身的形成。","這句說明目標需要甚麼品質，以及人為何願意付出代價。","這句由常見失敗推到堅持的必要性，未列出具體個案。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-04","frame":"The first reason [特質] is essential is that it sustains [必要行動] over [較長時間]","meaning":"用 is that 清楚指出第一理由的機制：某特質讓需要的努力延續。","usage":"第一主體段要從引言的雙理由中展開「能長期堅持」的一條時。","source":{"paragraph":2,"sentence":1},"parts":[{"text":"The first reason ","kind":"link","label":"引出第一理由"},{"text":"ambition","kind":"slot","label":"特質"},{"text":" is essential is that it sustains ","kind":"link","label":"指出持續作用"},{"text":"effort","kind":"slot","label":"必要行動"},{"text":" over ","kind":"link","label":"指出持續時間"},{"text":"long periods of time.","kind":"slot","label":"較長時間"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["The first reason patient teaching matters is that it keeps children practising over many months.","Many parents therefore believe that daily reading helps children build confidence.","I completely agree, because regular practice gives learners both stronger memory and the confidence to speak until new words become useful in conversation.","Just as importantly, a clear goal helps athletes recover from injuries instead of ending their plans after one bad season."],"correct":0,"explanations":["is that 將首項理由具體化為長期維持練習。","這句是依前文轉述他人看法，沒有解釋成果本身的形成。","這句用雙重助力支持立場並指向成果，不只是轉述他人看法。","這句先標示同等重要的另一作用，再對照兩個不同後續行動。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-05","frame":"[有價值目標] normally demands [必要品質], and [有強烈目標者] are more willing to [承受不便] in order to [達成目標]","meaning":"先說成功需要紀律，再說有抱負者願意承擔不便，因為他們有目標。","usage":"要解釋抱負如何轉化為每天實際付出的時間與不便時。","source":{"paragraph":2,"sentence":2},"parts":[{"text":"Real success","kind":"slot","label":"有價值目標"},{"text":" normally demands ","kind":"link","label":"提出要求"},{"text":"discipline","kind":"slot","label":"必要品質"},{"text":", and ","kind":"link","label":"接人的行為"},{"text":"ambitious people","kind":"slot","label":"有強烈目標者"},{"text":" are far more willing to ","kind":"link","label":"表達較高意願"},{"text":"tolerate inconvenience","kind":"slot","label":"承受不便"},{"text":" in order to ","kind":"link","label":"指出目的"},{"text":"reach a goal.","kind":"slot","label":"達成目標"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Learning to play an instrument normally demands practice, and serious pupils are more willing to give up free evenings in order to improve.","I completely agree, because regular practice gives learners both stronger memory and the confidence to speak until new words become useful in conversation.","The first reason patient teaching matters is that it keeps children practising over many months.","Because learning a language involves mistakes and repeated practice, continuing after a weak test result is necessary; it is part of progress."],"correct":0,"explanations":["normally demands...and...in order to 連起要求、付出的代價與目標。","這句用雙重助力支持立場並指向成果，不只是轉述他人看法。","這句點明第一個主體段的核心原因，沒有並列兩項作用。","這句由常見失敗推到堅持的必要性，未列出具體個案。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-06","frame":"[為目標努力的人], for example, may [持續行動一], [減少享樂二] and [長期練習三]","meaning":"用一名學生及多項日常行動展示「願意忍受不便」如何具體發生。","usage":"剛提出長期紀律與代價，需用可信的人物例子使其可見時。","source":{"paragraph":2,"sentence":3},"parts":[{"text":"A student aiming for a highly competitive scholarship","kind":"slot","label":"為目標努力的人"},{"text":", for example, may ","kind":"link","label":"引出可能行動"},{"text":"spend evenings revising","kind":"slot","label":"持續行動一"},{"text":", ","kind":"link","label":"並列"},{"text":"reduce social activities","kind":"slot","label":"減少享樂二"},{"text":" and ","kind":"link","label":"並列"},{"text":"practise under constant pressure for months.","kind":"slot","label":"長期練習三"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["A runner preparing for a difficult race, for example, may train before work, skip some parties and keep practising for months.","The first reason patient teaching matters is that it keeps children practising over many months.","Learning to play an instrument normally demands practice, and serious pupils are more willing to give up free evenings in order to improve.","When a young musician performs badly at a first concert, a clear goal encourages practice rather than an immediate decision to quit."],"correct":0,"explanations":["for example 引出具體人物；may 列出可能的持續投入。","這句點明第一個主體段的核心原因，沒有並列兩項作用。","這句說明目標需要甚麼品質，以及人為何願意付出代價。","這句在具體挫敗下比較兩種反應，不是泛稱面對挫折的能力。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-07","frame":"Just as importantly, [推動因素] helps [人] recover from [挫折] instead of [過早放棄]","meaning":"Just as importantly 轉入同等重要的作用；instead of 對照受挫後繼續與放棄兩種行動。","usage":"談過長期投入後，還要解釋人失敗一次時如何保持方向時。","source":{"paragraph":2,"sentence":4},"parts":[{"text":"Just as importantly, ","kind":"link","label":"引出同等重要作用"},{"text":"ambition","kind":"slot","label":"推動因素"},{"text":" helps people recover from ","kind":"link","label":"指出恢復作用"},{"text":"setbacks","kind":"slot","label":"挫折"},{"text":" instead of ","kind":"link","label":"對照不採取的行動"},{"text":"abandoning their plans at the first disappointment.","kind":"slot","label":"過早放棄"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Just as importantly, a clear goal helps athletes recover from injuries instead of ending their plans after one bad season.","Learning to play an instrument normally demands practice, and serious pupils are more willing to give up free evenings in order to improve.","A runner preparing for a difficult race, for example, may train before work, skip some parties and keep practising for months.","Because learning a language involves mistakes and repeated practice, continuing after a weak test result is necessary; it is part of progress."],"correct":0,"explanations":["instead of 對照遭挫後的兩種選擇：恢復再試與放棄。","這句說明目標需要甚麼品質，以及人為何願意付出代價。","這句以一個具體人物和三項行動展示長期代價，不是在下抽象判斷。","這句由常見失敗推到堅持的必要性，未列出具體個案。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-08","frame":"When [具體受挫情況], [推動因素] encourages [檢查問題並再試] rather than [認定不能成功]","meaning":"把抽象的「從挫折恢復」落到模擬考失利後的兩種可見反應。","usage":"已說抱負有助從挫折恢復，接着要用同一人物展示真正的下一步時。","source":{"paragraph":2,"sentence":5},"parts":[{"text":"When ","kind":"link","label":"設定具體受挫情況"},{"text":"such a student performs badly in an early mock exam","kind":"slot","label":"具體受挫情況"},{"text":", ","kind":"link","label":"接反應"},{"text":"ambition","kind":"slot","label":"推動因素"},{"text":" encourages them to ","kind":"link","label":"促使採取行動"},{"text":"analyse weaknesses and try again","kind":"slot","label":"檢查問題並再試"},{"text":" rather than ","kind":"link","label":"對照被避免的反應"},{"text":"conclude that success is impossible.","kind":"slot","label":"認定不能成功"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["When a young musician performs badly at a first concert, a clear goal encourages practice rather than an immediate decision to quit.","A runner preparing for a difficult race, for example, may train before work, skip some parties and keep practising for months.","Just as importantly, a clear goal helps athletes recover from injuries instead of ending their plans after one bad season.","Because learning a language involves mistakes and repeated practice, continuing after a weak test result is necessary; it is part of progress."],"correct":0,"explanations":["When 設定失敗情況，rather than 對照反思再試與立即退出。","這句以一個具體人物和三項行動展示長期代價，不是在下抽象判斷。","這句先標示同等重要的另一作用，再對照兩個不同後續行動。","這句由常見失敗推到堅持的必要性，未列出具體個案。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-09","frame":"Because [有價值成果通常經過代價與失敗], [持續行動] is not optional; it is fundamental","meaning":"把例子的意義提升為一般原則：若成果常在代價與失敗後出現，堅持便不可缺。","usage":"已用例子展示長期練習及考試失利後再試，要收束第一段時。","source":{"paragraph":2,"sentence":6},"parts":[{"text":"Because ","kind":"link","label":"提出普遍原因"},{"text":"achievement usually comes after sacrifice and failure","kind":"slot","label":"有價值成果通常經過代價與失敗"},{"text":", ","kind":"link","label":"推出判斷"},{"text":"this kind of persistence","kind":"slot","label":"持續行動"},{"text":" is not optional; it is fundamental.","kind":"link","label":"強調必要性"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Because learning a language involves mistakes and repeated practice, continuing after a weak test result is necessary; it is part of progress.","I completely agree, because regular practice gives learners both stronger memory and the confidence to speak until new words become useful in conversation.","A runner preparing for a difficult race, for example, may train before work, skip some parties and keep practising for months.","When a young musician performs badly at a first concert, a clear goal encourages practice rather than an immediate decision to quit."],"correct":0,"explanations":["Because 統合先前例子，分號後再強化必要性。","這句用雙重助力支持立場並指向成果，不只是轉述他人看法。","這句以一個具體人物和三項行動展示長期代價，不是在下抽象判斷。","這句在具體挫敗下比較兩種反應，不是泛稱面對挫折的能力。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-10","frame":"[推動因素] is equally important because it pushes [人] beyond [僅僅達標的程度]","meaning":"第二主體段把焦點從能否堅持，轉到是否會主動超越「夠用」的水平。","usage":"第一段已論證持續努力，第二段要展開改進與成長這條新理由時。","source":{"paragraph":3,"sentence":1},"parts":[{"text":"Ambition","kind":"slot","label":"推動因素"},{"text":" is equally important because it pushes ","kind":"link","label":"指出第二項作用"},{"text":"people","kind":"slot","label":"人"},{"text":" beyond ","kind":"link","label":"超越"},{"text":"mere competence.","kind":"slot","label":"僅僅達標的程度"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Curiosity is equally important because it pushes students beyond memorising answers.","The first reason patient teaching matters is that it keeps children practising over many months.","Because learning a language involves mistakes and repeated practice, continuing after a weak test result is necessary; it is part of progress.","Dedicated volunteers do not simply repeat last year’s plan; they seek better methods and take harder tasks."],"correct":0,"explanations":["because 引出第二主體段的另一作用：超越最低要求。","這句點明第一個主體段的核心原因，沒有並列兩項作用。","這句由常見失敗推到堅持的必要性，未列出具體個案。","這句用分號對照兩種行動，具體展開「不只夠用」。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-11","frame":"Those who [真正想達成目標] do not simply [重複熟悉做法]; they actively seek [更好方法、更高標準與更難責任]","meaning":"分號兩邊形成對照：不滿足於照舊做，而是主動提高方法、標準與承擔。","usage":"要解釋「超越勝任」究竟表現為哪些可觀察行動時。","source":{"paragraph":3,"sentence":2},"parts":[{"text":"Those who ","kind":"link","label":"限定討論的人"},{"text":"genuinely want to succeed","kind":"slot","label":"真正想達成目標"},{"text":" do not simply ","kind":"link","label":"否定被動做法"},{"text":"repeat familiar routines","kind":"slot","label":"重複熟悉做法"},{"text":"; they actively seek ","kind":"link","label":"轉向主動改進"},{"text":"better methods, higher standards and more demanding responsibilities.","kind":"slot","label":"更好方法、更高標準與更難責任"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Dedicated volunteers do not simply repeat last year’s plan; they seek better methods and take harder tasks.","Just as importantly, a clear goal helps athletes recover from injuries instead of ending their plans after one bad season.","Curiosity is equally important because it pushes students beyond memorising answers.","A serious cook, for instance, is more likely to test new recipes, ask diners for comments and practise presentation in order to run a better restaurant."],"correct":0,"explanations":["do not simply...; they... 對照被動重複與主動改進。","這句先標示同等重要的另一作用，再對照兩個不同後續行動。","這句由先前的堅持轉向能力提升，沒有重述第一段的失敗例子。","這句以人物、三項準備及目的展示改進，不是一般性的分號對照。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-12","frame":"[有抱負的工作者], for instance, is more likely to [學新工具], [要求回饋] and [強化技能] in order to [準備晉升]","meaning":"用員工學工具、求意見和改善溝通的例子，展示目標如何促進技能提升。","usage":"已說有目標的人會改進，接着要舉職場上的具體行動時。","source":{"paragraph":3,"sentence":3},"parts":[{"text":"An ambitious employee","kind":"slot","label":"有抱負的工作者"},{"text":", for instance, is more likely to ","kind":"link","label":"審慎提出具體例子"},{"text":"learn new software","kind":"slot","label":"學新工具"},{"text":", ","kind":"link","label":"並列"},{"text":"request feedback","kind":"slot","label":"要求回饋"},{"text":" and ","kind":"link","label":"並列"},{"text":"strengthen communication skills","kind":"slot","label":"強化技能"},{"text":" in order to ","kind":"link","label":"交代目的"},{"text":"prepare for promotion.","kind":"slot","label":"準備晉升"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["A serious cook, for instance, is more likely to test new recipes, ask diners for comments and practise presentation in order to run a better restaurant.","Curiosity is equally important because it pushes students beyond memorising answers.","Dedicated volunteers do not simply repeat last year’s plan; they seek better methods and take harder tasks.","Interest in science also makes pupils alert to experiments that less curious classmates often ignore."],"correct":0,"explanations":["more likely to 審慎列出具體改進行動；in order to 指向目標。","這句由先前的堅持轉向能力提升，沒有重述第一段的失敗例子。","這句用分號對照兩種行動，具體展開「不只夠用」。","這句著眼於識別別人可能錯過的機會，而非技能訓練本身。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-13","frame":"[推動因素] also makes [人] alert to [某些機會] that [動力較低者] often ignore","meaning":"從培養技能轉到留意機會；that 指明這些機會也是別人容易忽略的。","usage":"已說明如何提升能力，還要解釋人怎樣發現可發揮能力的機會時。","source":{"paragraph":3,"sentence":4},"parts":[{"text":"Ambition","kind":"slot","label":"推動因素"},{"text":" also makes ","kind":"link","label":"促成新的警覺"},{"text":"people","kind":"slot","label":"人"},{"text":" alert to ","kind":"link","label":"注意到"},{"text":"opportunities","kind":"slot","label":"某些機會"},{"text":" that ","kind":"link","label":"限定這些機會"},{"text":"less driven individuals","kind":"slot","label":"動力較低者"},{"text":" often ignore.","kind":"link","label":"往往忽略"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Interest in science also makes pupils alert to experiments that less curious classmates often ignore.","Curiosity is equally important because it pushes students beyond memorising answers.","Dedicated volunteers do not simply repeat last year’s plan; they seek better methods and take harder tasks.","A serious cook, for instance, is more likely to test new recipes, ask diners for comments and practise presentation in order to run a better restaurant."],"correct":0,"explanations":["makes...alert to 連接推動因素與察覺機會；that 限定被忽略的機會。","這句由先前的堅持轉向能力提升，沒有重述第一段的失敗例子。","這句用分號對照兩種行動，具體展開「不只夠用」。","這句以人物、三項準備及目的展示改進，不是一般性的分號對照。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-14","frame":"The same [人] may [主動承擔難事] or [提出新構想], thereby gaining both [經驗] and [被看見的機會]","meaning":"以同一人物延續前例，說明怎樣採取行動，並以 thereby 表明所得結果。","usage":"已說人會看見機會，現在須展示他如何把機會變成經驗與曝光時。","source":{"paragraph":3,"sentence":5},"parts":[{"text":"The same ","kind":"link","label":"延續前一例子"},{"text":"worker","kind":"slot","label":"人"},{"text":" may ","kind":"link","label":"提出可能行動"},{"text":"volunteer for a difficult project","kind":"slot","label":"主動承擔難事"},{"text":" or ","kind":"link","label":"提供另一行動"},{"text":"propose an innovative idea to senior managers","kind":"slot","label":"提出新構想"},{"text":", thereby gaining both ","kind":"link","label":"推出雙重所得"},{"text":"experience","kind":"slot","label":"經驗"},{"text":" and ","kind":"link","label":"並列"},{"text":"visibility.","kind":"slot","label":"被看見的機會"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["The same student may join a difficult science project or share an idea with teachers, thereby gaining experience and attention.","A serious cook, for instance, is more likely to test new recipes, ask diners for comments and practise presentation in order to run a better restaurant.","Interest in science also makes pupils alert to experiments that less curious classmates often ignore.","As a result, regular practice does not just sharpen a pupil’s skills; it puts those skills on show where teachers can notice and value them."],"correct":0,"explanations":["may 審慎提出可能行動；thereby 指出由行動得到的兩項結果。","這句以人物、三項準備及目的展示改進，不是一般性的分號對照。","這句著眼於識別別人可能錯過的機會，而非技能訓練本身。","這句從前述行動推到兩種不同作用：改善能力並使其有機會被認可。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-15","frame":"As a result, [推動因素] does not just improve [能力]; it places that ability in situations where it can be [看見並回報]","meaning":"總結第二段的兩層作用：抱負既提升能力，也使能力有被認可及回報的場合。","usage":"已舉學技能與主動承擔兩類行動，要說明兩者合起來為何促成成就時。","source":{"paragraph":3,"sentence":6},"parts":[{"text":"As a result, ","kind":"link","label":"從前述行動得出結果"},{"text":"ambition","kind":"slot","label":"推動因素"},{"text":" does not just improve ","kind":"link","label":"第一層作用"},{"text":"a person’s ability","kind":"slot","label":"能力"},{"text":"; it places that ability in situations where it can be ","kind":"link","label":"第二層作用：進入可見場景"},{"text":"recognised and rewarded.","kind":"slot","label":"看見並回報"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["As a result, regular practice does not just sharpen a pupil’s skills; it puts those skills on show where teachers can notice and value them.","Dedicated volunteers do not simply repeat last year’s plan; they seek better methods and take harder tasks.","Interest in science also makes pupils alert to experiments that less curious classmates often ignore.","The same student may join a difficult science project or share an idea with teachers, thereby gaining experience and attention."],"correct":0,"explanations":["not just...; it... 把能力提高與使能力被看見區分開來。","這句用分號對照兩種行動，具體展開「不只夠用」。","這句著眼於識別別人可能錯過的機會，而非技能訓練本身。","這句把察覺機會落到具體參與與所得，不只說會注意。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-16","frame":"In conclusion, I completely agree that [核心特質] is essential for [目標]","meaning":"結論直接回到題目，清楚重申「完全同意」與核心判斷，不引入新材料。","usage":"兩段理由已論證完，要用一句話先回答題目的同意程度時。","source":{"paragraph":4,"sentence":1},"parts":[{"text":"In conclusion, I completely agree that ","kind":"link","label":"重申完全同意"},{"text":"ambition","kind":"slot","label":"核心特質"},{"text":" is essential for ","kind":"link","label":"說明必要關係"},{"text":"success.","kind":"slot","label":"目標"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In conclusion, I completely agree that patient practice is essential for learning a language.","Many parents therefore believe that daily reading helps children build confidence.","Curiosity is equally important because it pushes students beyond memorising answers.","It helps learners practise regularly, learn from mistakes, try better methods and use new chances, and these are the conditions in which progress becomes possible."],"correct":0,"explanations":["結論直接重申立場與必要條件，沒有加入新理由。","這句是依前文轉述他人看法，沒有解釋成果本身的形成。","這句由先前的堅持轉向能力提升，沒有重述第一段的失敗例子。","這句列出幾項作用並作歸納，不只是重申同意程度。"],"patternType":"reviewed"},{"id":"model-essay-13-ielts-opinion-frame-17","frame":"It enables [人] to [承受代價], [失敗後恢復], [追求改進] and [把握機會], and these are precisely the conditions in which [成果] becomes possible","meaning":"結論把堅持與提升兩段的四個作用併列，再說明它們如何使成果有可能。","usage":"最後一句須回收兩條主線，不增添新例子，並指出成功形成的條件時。","source":{"paragraph":4,"sentence":2},"parts":[{"text":"It enables ","kind":"link","label":"指回核心特質的作用"},{"text":"people","kind":"slot","label":"人"},{"text":" to ","kind":"link","label":"引出四種行動"},{"text":"endure sacrifice","kind":"slot","label":"承受代價"},{"text":", ","kind":"link","label":"並列"},{"text":"recover from failure","kind":"slot","label":"失敗後恢復"},{"text":", ","kind":"link","label":"並列"},{"text":"pursue improvement","kind":"slot","label":"追求改進"},{"text":" and ","kind":"link","label":"並列"},{"text":"seize opportunities","kind":"slot","label":"把握機會"},{"text":", and these are precisely the conditions in which ","kind":"link","label":"歸納成功條件"},{"text":"meaningful achievement","kind":"slot","label":"成果"},{"text":" becomes possible.","kind":"link","label":"指出可能性"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["It helps learners practise regularly, learn from mistakes, try better methods and use new chances, and these are the conditions in which progress becomes possible.","I completely agree, because regular practice gives learners both stronger memory and the confidence to speak until new words become useful in conversation.","Because learning a language involves mistakes and repeated practice, continuing after a weak test result is necessary; it is part of progress.","In conclusion, I completely agree that patient practice is essential for learning a language."],"correct":0,"explanations":["四項行動回收兩段理由，and these are... 說明它們構成成果條件。","這句用雙重助力支持立場並指向成果，不只是轉述他人看法。","這句由常見失敗推到堅持的必要性，未列出具體個案。","這句是結論中的立場重申，未列出四個形成成果的條件。"],"patternType":"reviewed"}],"transfer":[{"type":"quiz","prompt":"哪項最能運用「長時間維持努力」的論證？","context":"一名學生想獲得需要全年準備的交換名額，但最近幾週成績還未改善。","question":"哪項最能運用「長時間維持努力」的論證？","options":["訂下每週練習與檢討計畫，持續觀察進步，而非只憑一週成績判斷","只在申請前一晚準備，因短期衝刺等同全年紀律","只談交換名額的重要，卻不安排任何日常練習","因數週未見改善，便斷定全年準備不可能有成果"],"correct":0,"explanations":["這把強烈目標轉成持續行動，保留原文的長期努力機制。","一晚準備不能代替長期練習。","目標本身不等於實際行動。","短期成績不能證明長期努力無效。"],"why":"這把強烈目標轉成持續行動，保留原文的長期努力機制。","sourceSentenceIndices":[2,3,4,5],"modelLink":"範文以獎學金學生的長期溫習與社交取捨，說明抱負如何維持努力。"},{"type":"quiz","prompt":"哪項下一步最符合範文的「從挫折恢復」？","context":"一名初學游泳者第一次比賽成績很差，卻仍想完成更長的賽程。","question":"哪項下一步最符合範文的「從挫折恢復」？","options":["檢視起跳與換氣問題，調整訓練後再參賽","不看比賽紀錄，只維持完全相同的錯誤動作","因一次比賽失利，立即認定自己永遠無法進步","只說想進步，卻取消往後所有練習"],"correct":0,"explanations":["這對應失利後分析弱點並再試的具體次序。","原文強調分析弱點，不只是機械重複。","一次失利不能證明成功不可能。","目標若不化成再試便不能產生作用。"],"why":"這對應失利後分析弱點並再試的具體次序。","sourceSentenceIndices":[6,7,8],"modelLink":"範文用模擬考表現差的學生，對照「分析弱點再試」與「認定不可能」。"},{"type":"quiz","prompt":"哪項最能把抱負轉成「超越僅僅勝任」？","context":"某員工多年完成本職工作，但希望申請需要新技能的職位。","question":"哪項最能把抱負轉成「超越僅僅勝任」？","options":["學相關軟件、向同事求回饋，並練習新職位需要的溝通方式","只把個人目標寫在履歷上，不更新技能","繼續完全相同的工作方法，同時假定能力已自動提高","避開所有回饋，因指出弱點會妨礙改進"],"correct":0,"explanations":["這把晉升目標連到三項可觀察的技能改進。","宣稱目標不等於做好準備。","重複熟悉做法不會自動滿足新職位要求。","回饋是原文員工主動尋求的改進資料。"],"why":"這把晉升目標連到三項可觀察的技能改進。","sourceSentenceIndices":[9,10,11],"modelLink":"範文指出有抱負員工學軟件、求回饋、改善溝通以準備晉升。"},{"type":"quiz","prompt":"哪項最能運用「能力需要被看見」？","context":"一名學生擅長寫程式，但校內作品一直沒有人看過；最近出現公開專題機會。","question":"哪項最能運用「能力需要被看見」？","options":["參與專題並展示作品，同時用評語繼續改善程式","只在私下修改程式，並拒絕任何可展示成果的機會","只報名專題，不準備可展示的實際作品","認為技能一提高，所有人就必定已知道"],"correct":0,"explanations":["這同時保留能力改進和把能力放進可被看見的情境。","私下改進技能未必帶來認可機會。","曝光須有實際能力或作品支撐。","他人不一定會自動看見私下的改進。"],"why":"這同時保留能力改進和把能力放進可被看見的情境。","sourceSentenceIndices":[11,12,13,14],"modelLink":"範文說抱負既提升能力，也使能力進入可被認可的場合。"},{"type":"quiz","prompt":"哪項最貼近範文的改進邏輯？","context":"一名年輕廚師希望成為主廚，已反覆煮熟悉的菜式，但從不詢問食客意見。","question":"哪項最貼近範文的改進邏輯？","options":["嘗試更好的做法、請人評價成品，再承擔較難的菜單工作","只增加同一道菜的份量，便視為方法已進步","完全避開批評，因回饋與技能提升沒有關係","只等待主廚職位出缺，不做任何準備"],"correct":0,"explanations":["這對應新方法、回饋與更難責任三項主動行動。","數量增加不等於方法或標準提高。","原文把要求回饋列為改進途徑。","職位空缺不會自動帶來所需能力。"],"why":"這對應新方法、回饋與更難責任三項主動行動。","sourceSentenceIndices":[9,10,11],"modelLink":"範文區分重複熟悉做法與主動找更好方法、更高標準和更難責任。"},{"type":"quiz","prompt":"哪項最能結合抱負與現實調整？","context":"志願者想改善社區圖書館，提出長期計畫後，首次活動只來了少量居民。","question":"哪項最能結合抱負與現實調整？","options":["查詢居民未參加的原因，調整活動並繼續推行一段時間","把一次參與人數少當作計畫永遠不可能成功的證明","只重做完全相同的活動，不問哪一步出了問題","因有長期目標，便認為活動成效毋須再觀察"],"correct":0,"explanations":["這將持續投入與檢討弱點合起來，而不把抱負當保證。","一次失利不足以判定長期目標不可能。","反思弱點是原文受挫再試的核心。","抱負仍須與實際表現資料配合。"],"why":"這將持續投入與檢討弱點合起來，而不把抱負當保證。","sourceSentenceIndices":[3,6,7,8],"modelLink":"範文指出抱負使人長期努力，遇初次失敗後分析弱點而非放棄。"},{"type":"quiz","prompt":"哪項最能把「改進」與「機會」兩段接起來？","context":"一名護士想轉入管理工作，院方正在徵求可負責小型改善項目的人。","question":"哪項最能把「改進」與「機會」兩段接起來？","options":["先學必要管理技能並請教同事，再主動申請帶領改善項目","只學技能，並避開所有可運用技能的工作","只報名領導項目，不了解需要掌握甚麼技能","只向院方說自己有抱負，卻不提出任何行動"],"correct":0,"explanations":["技能準備與實際承擔相接，能力才有機會被看見。","有技能但不用於機會，可能難獲認可。","只求曝光而不作準備，缺少能力基礎。","抱負須透過具體改進與參與發揮作用。"],"why":"技能準備與實際承擔相接，能力才有機會被看見。","sourceSentenceIndices":[10,11,12,13,14],"modelLink":"範文的員工先學新軟件、求回饋，再接難項目取得經驗與曝光。"},{"type":"quiz","prompt":"哪項最完整套用第一主體段？","context":"一名樂手為演出練習數月，首場表現欠佳，但演出機構仍提供第二次試演。","question":"哪項最完整套用第一主體段？","options":["保留長期練習，分析首演問題，並為第二次試演調整做法","因已練習數月，便認為首場表現不需檢討","因首場欠佳，便取消往後全部練習和試演","只要求更多試演機會，不改善演出內容"],"correct":0,"explanations":["這兼顧長期付出與受挫後的具體修正。","持續投入仍須配合分析弱點。","第一次失望不是立即放棄的充分理由。","機會只有配合改進才更可能轉成成果。"],"why":"這兼顧長期付出與受挫後的具體修正。","sourceSentenceIndices":[4,5,6,7,8],"modelLink":"範文第一段既談長期練習，也談模擬考失利後分析弱點再試。"},{"type":"quiz","prompt":"哪項最能轉用「留意並把握機會」？","context":"一名研究生看見跨學科研究徵集，題目困難但與自己的新技能有關。","question":"哪項最能轉用「留意並把握機會」？","options":["評估所需工作後申請，並在項目中累積經驗及展示技能","因題目困難便不讀要求，直接認定自己沒有可能參與","只私下練習技能，卻從不留意任何可參與的項目","不準備相關技能，只希望參與便保證得到認可"],"correct":0,"explanations":["這把察覺機會、主動承擔與能力被看見連起來。","題目困難不等於毋須了解條件。","技能與可運用技能的場合都重要。","參與不保證回報，仍需要相關準備。"],"why":"這把察覺機會、主動承擔與能力被看見連起來。","sourceSentenceIndices":[12,13,14],"modelLink":"範文以主動請纓艱難項目，說明如何取得經驗與可見性。"},{"type":"quiz","prompt":"哪項最能運用「超越僅僅勝任」？","context":"一間小型劇團想吸引更廣觀眾，團員技術穩定，但一直演出同一套舊節目。","question":"哪項最能運用「超越僅僅勝任」？","options":["試驗新演法、徵求觀眾回饋，再承擔更具挑戰的演出","只重複舊節目，因技術穩定便不需要改進","只提高宣傳預算，卻不觀察節目或演法能否改善","把觀眾回饋視為必須完全避免的干擾"],"correct":0,"explanations":["這把主動找新方法、較高標準和更難責任轉用到表演。","穩定勝任與繼續提高不是同一回事。","宣傳可增加曝光，但這裡要檢驗能力改進。","回饋能協助判斷應如何調整。"],"why":"這把主動找新方法、較高標準和更難責任轉用到表演。","sourceSentenceIndices":[9,10,11],"modelLink":"範文說真正想成功的人不只重複熟悉做法，而會找更好方法及更高標準。"},{"type":"quiz","prompt":"哪項回應最符合文章的實際論證？","context":"一位學生說「我有抱負，所以一定會成功」，卻沒有安排練習或參與任何專題。","question":"哪項回應最符合文章的實際論證？","options":["抱負要化成持續練習、遇錯再試、改善技能及把握機會，才可能產生成果","只要說出抱負，四項行動就會自動發生","沒有參與專題也沒有練習，能力仍必然被看見","因抱負重要，便可把所有失敗和回饋完全忽略"],"correct":0,"explanations":["這把結論四項作用還原成可執行行動，並保留「可能」而非保證。","宣稱有抱負不能代替行動。","能力與曝光都需要具體條件。","文章正強調從失敗學習。"],"why":"這把結論四項作用還原成可執行行動，並保留「可能」而非保證。","sourceSentenceIndices":[2,7,10,13,14,16],"modelLink":"範文結論把犧牲、從失敗恢復、改進及把握機會列為成果形成的條件。"},{"type":"quiz","prompt":"哪項行動順序最貼近兩個主體段？","context":"一名教師想推動閱讀計畫：前期要額外備課，試行後可能須改動方法，並可向全校分享。","question":"哪項行動順序最貼近兩個主體段？","options":["先持續備課與試行，根據反饋修正，再主動分享有效做法","只向全校宣布目標，省略備課、試行與回饋","首次試行不順便立即停止，也不檢查原因","只長期備課，不檢驗方法或讓他人看見成果"],"correct":0,"explanations":["這將承受代價、從失敗調整、改善方法和抓住展示機會依序連接。","宣布目標不能代替實施過程。","遇挫後的分析再試是第一段重點。","第二段還要求改進和把能力置於可見場合。"],"why":"這將承受代價、從失敗調整、改善方法和抓住展示機會依序連接。","sourceSentenceIndices":[4,6,7,10,12,13,14,16],"modelLink":"範文兩段由堅持與受挫再試，推進到改進方法及主動把握機會。"}],"mediumExtras":[]};})();
